+                  </div>
+                );
+              })}
+            </div>
+          </div>
+          <div className="dt-body" role="rowgroup" style={{ height: processedRows.length * rowHeight }}>
+            {visibleRows.map((row, localIndex) => {
+              const rowIndex = firstVisible + localIndex;
+              const rowId = getRowId(row);
