+  const orderedColumns = useMemo(
+    () =>
+      columnOrder
+        .map((id) => columns.find((column) => column.id === id))
+        .filter((column): column is DataColumn<T> => Boolean(column)),
+    [columnOrder, columns],
+  );
+
+  const getValue = (row: T, column: DataColumn<T>): unknown => {
